import{_ as t,o as a,c as i,a0 as r}from"./chunks/framework.DPd3ST4h.js";const h=JSON.parse('{"title":"Portable review application","description":"","frontmatter":{},"headers":[],"relativePath":"portable-architecture.md","filePath":"portable-architecture.md","lastUpdated":1793438012000}'),o={name:"portable-architecture.md"};function n(s,e,c,d,p,l){return a(),i("div",null,[...e[0]||(e[0]=[r(`<h1 id="portable-review-application" tabindex="-1">Portable review application <a class="header-anchor" href="#portable-review-application" aria-label="Permalink to &quot;Portable review application&quot;">​</a></h1><p>The local CLI and existing GitHub integration share the review runner, bundle builder, prompt policy, validation, artifact schemas, and harness executors. Revision capture and presentation remain outside the review core.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>redline review -&gt; validated LocalOptions -&gt; ReviewApplication</span></span>
<span class="line"><span>                                             |</span></span>
<span class="line"><span>                         +-------------------+--------------------+</span></span>
<span class="line"><span>                         |                   |                    |</span></span>
<span class="line"><span>                    RevisionSource      runFileReviews      CompositeReporter</span></span>
<span class="line"><span>                         |                   |                    |</span></span>
<span class="line"><span>                   GitRevisionSource    ReviewWriter          CliReporter</span></span>
<span class="line"><span>                    isolated objects    JSON + Markdown      bounded terminal</span></span>
<span class="line"><span></span></span>
<span class="line"><span>redline-review -&gt; existing environment/publication modes</span></span>
<span class="line"><span>                         |</span></span>
<span class="line"><span>                 executePreparedReview -&gt; same runFileReviews</span></span></code></pre></div><h2 id="responsibility-boundaries" tabindex="-1">Responsibility boundaries <a class="header-anchor" href="#responsibility-boundaries" aria-label="Permalink to &quot;Responsibility boundaries&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Pattern</th><th>Concrete responsibility</th></tr></thead><tbody><tr><td>Ports and Adapters</td><td><code>RevisionSource</code>, <code>ReviewReporter</code>, <code>ReviewWriter</code>, and the existing <code>HarnessExecutor</code> separate source capture, output, persistence, and model execution.</td></tr><tr><td>Application Service / Facade</td><td><code>ReviewApplication.run()</code> orders preflight, capture, optional context preparation, review, reporting, and disposal. <code>executePreparedReview()</code> preserves the prepared-bundle compatibility path.</td></tr><tr><td>Command</td><td>A validated <code>ReviewCommand</code> supplies explicit review configuration; the application does not read argv or ambient environment.</td></tr><tr><td>Strategy / Adapter</td><td><code>GitRevisionSource</code> captures Git states; <code>CliReporter</code> presents validated results. The existing harness registry selects Pi, OpenCode, or echo.</td></tr><tr><td>Factory / capability registry</td><td>The local composition root chooses adapters after <code>requireCapability()</code> checks known IDs. Planned values fail explicitly rather than loading arbitrary plugins.</td></tr><tr><td>Composite</td><td><code>CompositeReporter</code> preflights all children, isolates runtime failures, and records adapter IDs that failed.</td></tr><tr><td>Observer</td><td>Discriminated <code>ReviewEvent</code> values carry content-free lifecycle progress. The review-plan event exposes only bounded file IDs and review eligibility in manifest order; per-file events expose only identity and outcome. Events contain neither source paths nor model payloads.</td></tr><tr><td>Dependency injection</td><td>Source, reporters, artifact writer, execution function, cancellation signal, streams, and existing runner clock/executor seams are supplied explicitly.</td></tr></tbody></table><p>There is no inheritance hierarchy or plugin loader. Adding an adapter requires trusted package code and tests, not repository configuration. A pattern is used only when it has a concrete responsibility.</p><h2 id="capture-is-not-review-policy" tabindex="-1">Capture is not review policy <a class="header-anchor" href="#capture-is-not-review-policy" aria-label="Permalink to &quot;Capture is not review policy&quot;">​</a></h2><p><code>src/local/</code> owns CLI parsing, trusted user configuration, Git process controls, immutable capture, and terminal rendering. <code>src/application/</code> owns ordering and contracts. <code>src/review/</code> still owns fixed prompts, bounded evidence, model-result validation, synthesis, reuse, and deterministic artifact writing. <code>src/code-index/context.ts</code> prepares revision-bound context through the shared Python artifact builder in <code>src/code-index/export.py</code>. The source port supplies immutable base/head exports; local tool discovery stays in <code>src/local/context.ts</code>. The action keeps compatibility entrypoints under <code>github/code-index/</code>. <code>src/publish/</code> retains existing managed GitHub publication.</p><p><code>buildBundle()</code> accepts a bounded Git command port. The existing context-bundle CLI uses its original implementation; the local revision adapter supplies a scratch-repository implementation. Local capture does not require modifying the existing manifest or review schemas.</p><p>A working-tree review writes synthetic tree/commit objects into temporary metadata using read-only alternates to the original object store. It never copies hooks, index extensions, repository config, or executable attributes. Staged review reads stage-zero object IDs. Unstaged review compares a synthetic index baseline against captured working bytes. Eligibility still comes from the chosen committed base.</p><h2 id="context-preparation" tabindex="-1">Context preparation <a class="header-anchor" href="#context-preparation" aria-label="Permalink to &quot;Context preparation&quot;">​</a></h2><p>A captured revision can expose a provider-neutral context snapshot: namespace, immutable base/head IDs, and a lazy bounded source exporter. The application injects context preparation between capture and review. It does not construct environment-variable workarounds or move provider logic into a forge adapter.</p><p>The local composition root resolves only separately installed trusted providers/runtimes. The shared builder indexes sanitized base source with repository/provider configuration excluded, queries bounded relationships, and re-resolves related spans from captured head source. The same artifact loader and prompt builder then serve local and GitHub execution. Model/publication credentials never enter provider environments. Pinned CGC machine output uses a fixed wide terminal width because CGC 0.5.7 otherwise wraps long path strings inside JSON.</p><p>Unavailable or invalid context records explicit file-only coverage. Required mode checks every reviewed file after source validation and aborts before model calls on any file-only gap. Local provider state uses a private, bounded exact-base cache behind an OS-backed cross-process lease. A stable base-source pathname preserves CGC graph references, but base bytes are refreshed from captured Git objects before validation. Provider/version, platform, repository, base, and configuration changes invalidate reuse. Head-only changes reuse validated databases, not head evidence or model output. Per-run socket/head/home scratch is removed; persistent action cache orchestration remains unchanged. An imported artifact bypasses provider execution but not identity, schema, path, or source validation. No verifier is activated.</p><h2 id="artifacts-precede-reporters" tabindex="-1">Artifacts precede reporters <a class="header-anchor" href="#artifacts-precede-reporters" aria-label="Permalink to &quot;Artifacts precede reporters&quot;">​</a></h2><p>Artifact writing is mandatory and separate from output adapters. Reporters cannot select review files, change prompts, relax validation, or provide a verdict. Completion reporters receive a publication-safe projection containing the validated review, summary, omission classifications, and output path, not raw per-file model output. Each reporter receives an independent copy, so mutation cannot alter the authoritative result or another reporter&#39;s input.</p><p>Preflight failure aborts before source capture. Progress/completion failures are isolated; valid review artifacts remain available and the local CLI reports a nonzero reporter outcome. The application disposes a successful capture on completion or execution failure. The source adapter owns cleanup if capture itself fails.</p><p>The terminal adapter can also read bounded excerpts through <code>FindingDiffReader</code>, scoped to the private captured bundle supplied by the composition root. It verifies base/head identities and file IDs/paths, checks changed-line evidence and both span endpoints, and clips excerpts without modifying review records. It reads neither live repository files nor model-generated replacements as original diff context. Unavailable excerpts affect presentation only; artifacts, coverage, verdict, and exit policy remain authoritative.</p><h2 id="compatibility-and-future-work" tabindex="-1">Compatibility and future work <a class="header-anchor" href="#compatibility-and-future-work" aria-label="Permalink to &quot;Compatibility and future work&quot;">​</a></h2><p>The GitHub Action continues to invoke <code>src/review/cli.ts</code> with its existing <code>REDLINE_*</code> environment and two-phase publication flow. The npm <code>redline-review</code> launcher delegates to that same entrypoint. Action inputs, publication ownership/stale-head rules, output schemas, and verifier activation are unchanged. Rewiring the action belongs to #180.</p><p>Local VCS IDs: <code>git</code>, <code>jj</code>, <code>mercurial</code>. Local reporter IDs: <code>cli</code>, <code>github</code>, <code>forgejo</code>, <code>gitea</code>, <code>gitlab</code>, <code>bitbucket</code>. Only Git and the CLI reporter are implemented in the new command. Existing GitHub publication remains available through the legacy action path, not through <code>--reporter github</code> yet.</p><p>No editor protocol, TypeScript SDK, foreign-VCS semantics, or forge-specific configuration is promised by this epic. #179 defines editor JSON-RPC; the remaining roadmap epics add the other adapters. Thin editor clients must not duplicate review policy.</p><h2 id="generation-limits" tabindex="-1">Generation limits <a class="header-anchor" href="#generation-limits" aria-label="Permalink to &quot;Generation limits&quot;">​</a></h2><p>The trusted <code>max-output-tokens</code> setting is parsed at the CLI/environment boundary and passed through <code>HarnessSettings</code>; prompt content and repository policy cannot select it. Pi maps it to isolated model configuration. OpenCode maps it to the runtime output ceiling without replacing catalog context-window metadata. Unset settings preserve existing executor defaults. Explicit budgets invalidate semantic review reuse. Token and byte allowances are independent, bounded resources; reasoning allocation and dollar budgets remain outside this interface.</p><h2 id="package-runtime" tabindex="-1">Package runtime <a class="header-anchor" href="#package-runtime" aria-label="Permalink to &quot;Package runtime&quot;">​</a></h2><p>The npm package contains trusted TypeScript source, fixed prompt data, and the shared standard-library Python exporter/JavaScript query adapter, with no runtime npm dependencies. Indexers and the optional Python helper runtime remain separately installed; no runtime or index database is embedded. Node.js does not automatically strip TypeScript inside <code>node_modules</code>; the package launchers install a synchronous load hook restricted to this package&#39;s <code>src/</code> URL prefix. The hook uses Node&#39;s <code>stripTypeScriptTypes()</code> in strip-only mode. It never loads reviewed repository modules or changes their execution permissions.</p><p>The installed tarball is tested outside the source checkout with <code>npm install --offline --ignore-scripts</code>. Both CLIs run from the installed copy. TypeScript remains checked with <code>tsc --noEmit</code> and <code>erasableSyntaxOnly</code>; there is no <code>dist/**/*.js</code> runtime contract and no install-time compiler. The CLI and artifact schemas are public contracts. Internal TypeScript modules are not exported as an SDK.</p>`,27)])])}const m=t(o,[["render",n]]);export{h as __pageData,m as default};
